/**
 * MRR fixtures (contracts/mrr_api_contract.md v1). MOCK BUILDS ONLY: scripts/check-no-mocks.mjs
 * fails the real build if a marker below leaks. summary.json and movements.json are generated by
 * generate_fixture.py from today's real files (silver engine); the identities of the contract are
 * asserted there. Discount steps, list MRR and discount MRR are null: there is no billing data.
 */
import type { MrrMovement, MrrMovementsPage, MrrSummary } from "../../src/lib/mrr/types";
import summary from "./summary.json";
import movements from "./movements.json";

export const MRR_MOCK_MARKER = "__MRR_MOCK_LAYER__";
export const MRR_RUN_ID = "r20261117T190000Z";

const SUMMARY = summary as unknown as MrrSummary;
const MOVEMENTS = movements as unknown as MrrMovement[];
const MONTH = /^\d{4}-(0[1-9]|1[0-2])$/;

export function mrrSummaryFor(run: string | null): MrrSummary | null {
  return !run || run === "latest" || run === MRR_RUN_ID ? SUMMARY : null;
}

type Detail = { check: string; field: string; message: string };

export function mrrMovementsFor(query: URLSearchParams): { status: number; body: unknown } {
  const run = query.get("run");
  if (!mrrSummaryFor(run)) return { status: 404, body: { error: { code: "unknown_run", message: "Unknown run." } } };
  const from = query.get("from") ?? "";
  const to = query.get("to") ?? "";
  const steps = query.getAll("step");
  const drivers = query.getAll("driver");
  const sort = query.get("sort") ?? "abs_desc";
  const page = Number(query.get("page") ?? "1");
  const pageSize = Number(query.get("page_size") ?? "50");
  const known = new Set(SUMMARY.steps.map((step) => step.code));
  const details: Detail[] = [];
  if (!MONTH.test(from)) details.push({ check: "MONTH", field: "from", message: "from must be YYYY-MM." });
  if (!MONTH.test(to)) details.push({ check: "MONTH", field: "to", message: "to must be YYYY-MM." });
  if (steps.some((step) => !known.has(step))) details.push({ check: "STEP", field: "step", message: "Unknown step code." });
  if (!["abs_desc", "asc", "desc"].includes(sort)) details.push({ check: "SORT", field: "sort", message: "Unknown sort." });
  if (!Number.isInteger(page) || page < 1 || !Number.isInteger(pageSize) || pageSize < 1 || pageSize > 200) {
    details.push({ check: "PAGING", field: "page", message: "page ≥ 1 and 1 ≤ page_size ≤ 200." });
  }
  if (details.length > 0) {
    return { status: 400, body: { error: { code: "invalid_query", message: "The query is not valid.", details } } };
  }
  let rows = MOVEMENTS.filter(
    (row) =>
      row.month >= from &&
      row.month <= to &&
      (steps.length === 0 || steps.includes(row.step)) &&
      (drivers.length === 0 || drivers.includes(row.driver)),
  );
  if (sort !== "abs_desc") {
    const sign = sort === "asc" ? 1 : -1;
    rows = [...rows].sort((a, b) => sign * (Number(a.change_value) - Number(b.change_value)));
  }
  const body: MrrMovementsPage = {
    run_id: MRR_RUN_ID,
    total: rows.length,
    page,
    page_size: pageSize,
    movements: rows.slice((page - 1) * pageSize, page * pageSize),
  };
  return { status: 200, body };
}
